execution.command_template:
printf '%s\x00%s' '{{action}}' '{{content}}' | python3 -c "
import sys
data = sys.stdin.read()
nul = data.index('\x00')
action = data[:nul]
content = data[nul+1:]
filename = 'findings.md'
try:
    lines = open(filename).readlines()
except FileNotFoundError:
    lines = ['# Findings\n', '## Summary\n', '-\n', '## Research Findings\n', '-\n', '## Technical Decisions\n', '-\n', '## Issues Encountered\n', '-\n']
start = None
end = None
for i, line in enumerate(lines):
    if line.rstrip('\n') == '## Summary':
        start = i
    elif start is not None and line.startswith('## ') and end is None:
        end = i
        break
if start is None:
    ins = 1 if lines and lines[0].startswith('#') else 0
    lines = lines[:ins] + ['## Summary\n'] + lines[ins:]
    start = ins
    end = ins + 1
if end is None:
    end = len(lines)
if action == 'replace':
    lines = lines[:start+1] + [content.strip() + '\n'] + lines[end:]
elif action == 'append':
    lines = lines[:end] + [content.strip() + '\n'] + lines[end:]
elif action == 'remove':
    section = [l for l in lines[start+1:end] if content.strip() not in l]
    lines = lines[:start+1] + section + lines[end:]
open(filename, 'w').writelines(lines)
print('Summary', action + 'd.')
"
